theorem tail_pairValue_pos {N : ℕ} {c τ η : ℝ} {t : Σ _ : ℕ, ℕ}
    (ht : t ∈ tailPairs N c τ η) : 0 < pairValue N t :=
  Nat.sub_pos_of_lt (tail_pair_product_lt ht)

theorem block_pairValue_pos {H : ℝ} {N : ℕ} {a η : ℝ} {t : Σ _ : ℕ, ℕ}
    (ht : t ∈ blockPairs H N a η) (hη : η ≤ 1) : 0 < pairValue N t :=
  Nat.sub_pos_of_lt (block_pair_product_lt ht hη)

theorem firstFeedbackWeightedKernel_nonneg {c u : ℝ}
    (hu : 0 < u) (huc : u < c) : 0 ≤ firstFeedbackWeightedKernel c u := by
  exact (div_pos (hu.trans huc) (mul_pos hu (sub_pos.mpr huc))).le

theorem gamma78Gain_denominator_pos {tri : Bool} {t u : ℝ}
    (hv : (t,u) ∈ gamma78GainRegion tri) : 0 < t*u*(1-t-u) :=
  (gamma5Gain_triangle_bounds (gamma78Gain_region_bounds hv).1).2.2.2.2

theorem cutoff_log_pos {η : ℝ} (hη : 0 < η) {N q : ℕ}
    (hN : 4 ≤ N) (hq : (N : ℝ) ^ η ≤ q) : 0 < log (q : ℝ) := by
  exact log_pos (cutoff_one_lt hη hN hq)

theorem roughFamily_original_mask {i N : ℕ} {δ Δ : ℝ} {V : Fin i → ℝ}
    (p : SecondFunctionalParameters) (j : Fin 6) {x : Label}
    (hx : x ∈ (roughFamily N δ Δ V p j).labels) :
    0 < x.2.2.2 ∧ Sifted (x.1*x.2.1*N) (cofactor x) x.2.2.1 :=
  source_mask p j ((mem_roughFamily_labels p j x).mp hx).1
